**json_test.go**

```go
package lesson

import (
	"bytes"
	"encoding/json"
	"reflect"
	"testing"
)

func TestMarshalAndEncoder(t *testing.T) {
	value := map[string]int{"count": 2}
	marshaled, err := json.Marshal(value)
	if err != nil {
		t.Fatal(err)
	}
	var buffer bytes.Buffer
	if err := json.NewEncoder(&buffer).Encode(value); err != nil {
		t.Fatal(err)
	}
	var first, second map[string]int
	if err := json.Unmarshal(marshaled, &first); err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(buffer.Bytes(), &second); err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(first, second) || buffer.Bytes()[buffer.Len()-1] != '\n' {
		t.Fatalf("marshal=%q encode=%q", marshaled, buffer.Bytes())
	}
}
```

**Run it**

```bash
go test -race ./...
go vet ./...
```

The test proves semantic equality while also showing Encoder's newline, which exact string comparisons often mistake for a contract change.
